<?php
$error=null;$role=role_name();$patient=patient_for_current_user();
if(request_method('POST')){require_roles(['Admin','Receptionist']);try{verify_csrf();$action=post_string('action');$invoiceId=(int)($_POST['invoice_id']??0);$stmt=db()->prepare('SELECT * FROM invoices WHERE invoice_id=?');$stmt->execute([$invoiceId]);$invoice=$stmt->fetch();if(!$invoice)throw new RuntimeException('Invoice not found.');if($invoice['status']!=='Active')throw new RuntimeException('This invoice is not active and cannot be modified.');if($action==='add_item'){$desc=post_string('description');$qty=(float)($_POST['quantity']??1);$price=(float)($_POST['unit_price']??0);if($desc===''||$qty<=0||$price<0)throw new RuntimeException('Enter a valid item, quantity and price.');$line=$qty*$price;db()->prepare("INSERT INTO invoice_items (invoice_id,item_type,description,quantity,unit_price,line_total) VALUES (?,'Other',?,?,?,?)")->execute([$invoiceId,$desc,$qty,$price,$line]);recalculate_invoice($invoiceId);log_action('ADD_INVOICE_ITEM','invoice_items',$invoiceId,null,['description'=>$desc,'line_total'=>$line]);flash('billing','Invoice item added.','success');redirect_to('billing',['invoice_id'=>$invoiceId]);}if($action==='discount'){$discount=max(0,(float)($_POST['discount_amount']??0));if($discount>(float)$invoice['subtotal'])throw new RuntimeException('Discount cannot exceed the subtotal.');db()->prepare('UPDATE invoices SET discount_amount=? WHERE invoice_id=?')->execute([$discount,$invoiceId]);recalculate_invoice($invoiceId);log_action('APPLY_DISCOUNT','invoices',$invoiceId,null,['discount'=>$discount]);flash('billing','Discount updated.','success');redirect_to('billing',['invoice_id'=>$invoiceId]);}if($action==='payment'){$amount=(float)($_POST['amount']??0);$method=post_string('payment_method');$allowedMethods=['Cash','Card','Mobile Banking','Bank Transfer'];if(!in_array($method,$allowedMethods,true))throw new RuntimeException('Select a valid payment method.');$pdo=db();$pdo->beginTransaction();$lockStmt=$pdo->prepare('SELECT * FROM invoices WHERE invoice_id=? FOR UPDATE');$lockStmt->execute([$invoiceId]);$lockedInvoice=$lockStmt->fetch();if(!$lockedInvoice||$lockedInvoice['status']!=='Active')throw new RuntimeException('This invoice is no longer available for payment.');recalculate_invoice($invoiceId);$due=(float)query_value('SELECT due_amount FROM invoices WHERE invoice_id=?',[$invoiceId]);if($amount<=0||$amount>$due+0.001)throw new RuntimeException('Payment must be positive and cannot exceed the current due amount of '.money($due).'.');$stmt=$pdo->prepare("INSERT INTO payments (invoice_id,amount,payment_method,transaction_reference,received_by,payment_date,payment_status,notes) VALUES (?,?,?,?,?,NOW(),'Completed',?)");$stmt->execute([$invoiceId,$amount,$method,nullable(post_string('transaction_reference')),current_user()['user_id'],nullable(post_string('notes'))]);$paymentId=(int)$pdo->lastInsertId();$number=payment_code($paymentId);$pdo->prepare('UPDATE payments SET payment_number=? WHERE payment_id=?')->execute([$number,$paymentId]);recalculate_invoice($invoiceId);$pdo->commit();notify_user(find_patient_user_id((int)$lockedInvoice['patient_id']),'Payment received',$number.' recorded for '.money($amount).'.','Billing','billing',$invoiceId);log_action('PAYMENT','payments',$paymentId,null,['amount'=>$amount,'invoice_id'=>$invoiceId]);flash('billing','Payment recorded successfully.','success');redirect_to('billing',['invoice_id'=>$invoiceId]);}}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$where=["i.status='Active'"];$params=[];if($role==='Patient'){$where[]='i.patient_id=?';$params[]=$patient['patient_id'];}if(get_string('status')!==''){$where[]='i.payment_status=?';$params[]=get_string('status');}$sql="SELECT i.*,p.patient_code,p.full_name patient_name,a.appointment_number FROM invoices i JOIN patients p ON p.patient_id=i.patient_id LEFT JOIN appointments a ON a.appointment_id=i.appointment_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY i.created_at DESC LIMIT 200";$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$selected=null;$items=[];$payments=[];$invoiceId=(int)($_GET['invoice_id']??0);if($invoiceId){$stmt=db()->prepare("SELECT i.*,p.patient_code,p.full_name patient_name,p.phone,p.email,a.appointment_number FROM invoices i JOIN patients p ON p.patient_id=i.patient_id LEFT JOIN appointments a ON a.appointment_id=i.appointment_id WHERE i.invoice_id=? AND i.status='Active'");$stmt->execute([$invoiceId]);$selected=$stmt->fetch();if($selected&&$role==='Patient'&&(int)$selected['patient_id']!==(int)$patient['patient_id'])$selected=null;if($selected){$stmt=db()->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY invoice_item_id');$stmt->execute([$invoiceId]);$items=$stmt->fetchAll();$stmt=db()->prepare('SELECT p.*,u.full_name received_by_name FROM payments p LEFT JOIN users u ON u.user_id=p.received_by WHERE p.invoice_id=? ORDER BY p.payment_date DESC');$stmt->execute([$invoiceId]);$payments=$stmt->fetchAll();}}
?>
<div class="page-header"><div><h2>Billing & payments</h2><p>Invoices, service charges, discounts, payments and outstanding balances.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<div class="grid grid-4 mb-2"><div class="card stat-card" style="--stat-color:#2563eb"><div><div class="stat-label">Invoices</div><div class="stat-value"><?=count($rows)?></div><div class="stat-note">Visible records</div></div><div class="stat-icon">▤</div></div><div class="card stat-card" style="--stat-color:#15803d"><div><div class="stat-label">Paid</div><div class="stat-value"><?=money(array_sum(array_map(fn($r)=>(float)$r['paid_amount'],$rows)))?></div><div class="stat-note">Total recorded</div></div><div class="stat-icon">✓</div></div><div class="card stat-card" style="--stat-color:#d97706"><div><div class="stat-label">Outstanding</div><div class="stat-value"><?=money(array_sum(array_map(fn($r)=>(float)$r['due_amount'],$rows)))?></div><div class="stat-note">Current due</div></div><div class="stat-icon">৳</div></div><div class="card stat-card" style="--stat-color:#7c3aed"><div><div class="stat-label">Fully paid</div><div class="stat-value"><?=count(array_filter($rows,fn($r)=>$r['payment_status']==='Paid'))?></div><div class="stat-note">Closed balances</div></div><div class="stat-icon">◎</div></div></div>
<?php if($selected):?><div class="grid grid-3 mb-2"><div class="card" style="grid-column:span 2"><div class="card-header"><div><h3><?=e($selected['invoice_number'])?></h3><p><?=e($selected['patient_name'])?> · <?=e($selected['appointment_number']??'Manual invoice')?></p></div><a class="btn btn-light" target="_blank" href="<?=e(route_url('print-invoice',['id'=>$selected['invoice_id']]))?>">Print invoice</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Description</th><th>Type</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['description'])?></td><td><?=e($item['item_type'])?></td><td><?=e($item['quantity'])?></td><td><?=money($item['unit_price'])?></td><td><?=money($item['line_total'])?></td></tr><?php endforeach;?></tbody></table></div><div style="max-width:330px;margin:18px 0 0 auto"><div style="display:flex;justify-content:space-between"><span>Subtotal</span><strong><?=money($selected['subtotal'])?></strong></div><div style="display:flex;justify-content:space-between"><span>Discount</span><strong>- <?=money($selected['discount_amount'])?></strong></div><div class="divider"></div><div style="display:flex;justify-content:space-between;font-size:20px"><span>Total</span><strong><?=money($selected['total_amount'])?></strong></div><div style="display:flex;justify-content:space-between"><span>Paid</span><strong class="text-success"><?=money($selected['paid_amount'])?></strong></div><div style="display:flex;justify-content:space-between"><span>Due</span><strong class="text-danger"><?=money($selected['due_amount'])?></strong></div></div><?php if(has_role(['Admin','Receptionist'])):?><div class="divider"></div><div class="grid grid-2"><form method="post" class="card" style="box-shadow:none;background:#f8fafc"><?=csrf_field()?><input type="hidden" name="action" value="add_item"><input type="hidden" name="invoice_id" value="<?=$selected['invoice_id']?>"><h4 class="mt-0">Add invoice item</h4><div class="field"><label>Description</label><input class="input" name="description" required></div><div class="form-grid"><div class="field"><label>Quantity</label><input class="input" type="number" min="0.01" step="0.01" name="quantity" value="1"></div><div class="field"><label>Unit price</label><input class="input" type="number" min="0" step="0.01" name="unit_price" required></div></div><button class="btn btn-light">Add item</button></form><form method="post" class="card" style="box-shadow:none;background:#f8fafc"><?=csrf_field()?><input type="hidden" name="action" value="discount"><input type="hidden" name="invoice_id" value="<?=$selected['invoice_id']?>"><h4 class="mt-0">Apply discount</h4><div class="field"><label>Discount amount</label><input class="input" type="number" min="0" step="0.01" name="discount_amount" value="<?=e($selected['discount_amount'])?>"></div><button class="btn btn-light">Update discount</button></form></div><?php endif;?></div>
<div class="card"><div class="card-header"><div><h3>Payments</h3><p>Transaction history.</p></div></div><?php foreach($payments as $p):?><div style="padding:10px 0;border-bottom:1px solid var(--line)"><strong><?=money($p['amount'])?></strong> <span class="badge badge-success"><?=e($p['payment_method'])?></span><div class="table-subtitle"><?=e($p['payment_number'])?> · <?=format_date($p['payment_date'],'d M Y, h:i A')?> · <?=e($p['received_by_name']??'System')?></div></div><?php endforeach;?><?php if(!$payments):?><p class="text-muted">No payments recorded.</p><?php endif;?><?php if(has_role(['Admin','Receptionist'])&&(float)$selected['due_amount']>0):?><div class="divider"></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="payment"><input type="hidden" name="invoice_id" value="<?=$selected['invoice_id']?>"><h4>Record payment</h4><div class="field"><label>Amount</label><input class="input" type="number" min="0.01" max="<?=e($selected['due_amount'])?>" step="0.01" name="amount" value="<?=e($selected['due_amount'])?>" required></div><div class="field"><label>Method</label><select class="select" name="payment_method"><option>Cash</option><option>Card</option><option>Mobile Banking</option><option>Bank Transfer</option></select></div><div class="field"><label>Transaction reference</label><input class="input" name="transaction_reference"></div><div class="field"><label>Notes</label><input class="input" name="notes"></div><button class="btn btn-primary btn-block">Record payment</button></form><?php endif;?></div></div><?php endif;?>
<div class="card"><div class="card-header"><div><h3>Invoice directory</h3><p>Open an invoice to see charges and transactions.</p></div><form method="get" class="actions"><input type="hidden" name="page" value="billing"><select class="select" name="status"><option value="">All statuses</option><?php foreach(['Unpaid','Partially Paid','Paid'] as $s):?><option <?=get_string('status')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-light">Filter</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Patient</th><th>Total</th><th>Paid</th><th>Due</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="table-title"><?=e($r['invoice_number'])?></td><td><?=e($r['patient_name'])?><div class="table-subtitle"><?=e($r['patient_code'])?></div></td><td><?=money($r['total_amount'])?></td><td><?=money($r['paid_amount'])?></td><td><?=money($r['due_amount'])?></td><td><span class="badge badge-<?=status_class($r['payment_status'])?>"><?=e($r['payment_status'])?></span></td><td><?=format_date($r['created_at'])?></td><td><a class="btn btn-primary btn-sm" href="<?=e(route_url('billing',['invoice_id'=>$r['invoice_id']]))?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></div>
